/* Expose the dataset to the shared loader (js/translators.js). */
window.TRANSLATORS = TRANSLATORS;


/* ==================================================
   HTML ESCAPING
   ================================================== */

function escapeHTML(value) {

    return String(value ?? '').replace(
        /[&<>"']/g,
        char => ({
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;'
        }[char])
    );

}


/* ==================================================
   GET UNIQUE LANGUAGE OPTIONS
   ================================================== */

function getLanguageOptions() {

    const langs = new Set();

    TRANSLATORS.forEach(t => {

        (t.languages || []).forEach(lang => {

            if (lang) langs.add(lang);

        });

    });

    return Array.from(langs).sort();

}


/* ==================================================
   GET UNIQUE DISTRICT OPTIONS
   ================================================== */

function getDistrictOptions() {

    const districts = new Set();

    TRANSLATORS.forEach(t => {

        if (
            t.district &&
            t.district !== 'Unknown'
        ) {

            districts.add(t.district);

        }

    });

    return Array.from(districts).sort();

}


/* ==================================================
   SEARCH AND FILTER TRANSLATORS
   ================================================== */

function filterTranslators(
    query = '',
    language = '',
    district = ''
) {

    const q = query.toLowerCase().trim();

    return TRANSLATORS.filter(t => {

        const matchesQuery = !q ||

            t.name.toLowerCase().includes(q) ||

            t.regNumber.toLowerCase().includes(q) ||

            t.address.toLowerCase().includes(q) ||

            t.tel.toLowerCase().includes(q) ||

            t.district.toLowerCase().includes(q);

        const matchesLanguage = !language ||

            (t.languages || []).includes(language);

        const matchesDistrict = !district ||

            t.district === district;

        return (
            matchesQuery &&
            matchesLanguage &&
            matchesDistrict
        );

    });

}


/* ==================================================
   RENDER TRANSLATOR CARDS
   ================================================== */

function renderTranslatorCards(translators, container) {

    if (!container) return;

    if (translators.length === 0) {

        container.innerHTML = `
            <div class="no-results">
                <div class="no-results-icon">🔍</div>
                <h3>No translators found</h3>
                <p>Try adjusting your search terms or filters.</p>
            </div>
        `;

        return;

    }

    container.innerHTML = translators.map(t => {

        const initials = escapeHTML(

            t.name.split(' ')
                .map(w => w[0])
                .slice(0, 2)
                .join('')
                .toUpperCase()

        );

        const languages = (t.languages || [])
            .map(lang =>
                `<span class="lang-tag">${escapeHTML(lang)}</span>`
            )
            .join('');

        return `
            <div class="translator-card fade-in visible">

                <div class="translator-card-header">

                    <div class="translator-avatar">
                        ${initials}
                    </div>

                    <div>

                        <div class="translator-name">
                            ${escapeHTML(t.name)}
                        </div>

                        <span class="translator-reg">
                            ${escapeHTML(t.regNumber)}
                        </span>

                    </div>

                </div>

                <div class="translator-details">

                    <div class="translator-detail">
                        <span class="detail-icon">📍</span>
                        <span>${escapeHTML(t.address)}</span>
                    </div>

                    <div class="translator-detail">
                        <span class="detail-icon">📞</span>
                        <span>${escapeHTML(t.tel)}</span>
                    </div>

                    <div class="translator-detail">
                        <span class="detail-icon">🏛️</span>
                        <span>${escapeHTML(t.district)}</span>
                    </div>

                </div>

                <div class="translator-languages">
                    ${languages}
                </div>

            </div>
        `;

    }).join('');

}


/* ==================================================
   REGISTRATION VERIFICATION
   ================================================== */

function verifyTranslator(regNumber) {

    const q = regNumber.trim().toUpperCase();

    return TRANSLATORS.find(

        t => t.regNumber.toUpperCase() === q

    ) || null;

}


/* ==================================================
   INITIALIZE DIRECTORY PAGE
   ================================================== */

function initDirectory() {

    const searchInput =
        document.getElementById('directorySearch');

    const langFilter =
        document.getElementById('langFilter');

    const districtFilter =
        document.getElementById('districtFilter');

    const grid =
        document.getElementById('translatorGrid');

    const countEl =
        document.getElementById('resultsCount');

    if (!grid) return;


    // Populate language filter

    if (langFilter) {

        getLanguageOptions().forEach(lang => {

            const opt = document.createElement('option');

            opt.value = lang;

            opt.textContent = lang;

            langFilter.appendChild(opt);

        });

    }


    // Populate district filter if available

    if (districtFilter) {

        getDistrictOptions().forEach(district => {

            const opt = document.createElement('option');

            opt.value = district;

            opt.textContent = district;

            districtFilter.appendChild(opt);

        });

    }


    // Update directory

    function update() {

        const query = searchInput
            ? searchInput.value
            : '';

        const lang = langFilter
            ? langFilter.value
            : '';

        const district = districtFilter
            ? districtFilter.value
            : '';

        const results = filterTranslators(
            query,
            lang,
            district
        );

        renderTranslatorCards(results, grid);

        if (countEl) {

            countEl.textContent =
                `Showing ${results.length} of ${TRANSLATORS.length} translators`;

        }

    }


    if (searchInput) {

        searchInput.addEventListener(
            'input',
            update
        );

    }

    if (langFilter) {

        langFilter.addEventListener(
            'change',
            update
        );

    }

    if (districtFilter) {

        districtFilter.addEventListener(
            'change',
            update
        );

    }


    // Initial render

    update();

}


/* ==================================================
   INITIALIZE VERIFICATION PAGE
   ================================================== */

function initVerification() {

    const input =
        document.getElementById('verifyInput');

    const btn =
        document.getElementById('verifyBtn');

    const resultDiv =
        document.getElementById('verifyResult');

    if (!btn || !input || !resultDiv) return;


    btn.addEventListener('click', () => {

        const reg = input.value.trim();

        if (!reg) {

            showVerifyResult(
                resultDiv,
                null,
                'Please enter a registration number.'
            );

            return;

        }

        const translator = verifyTranslator(reg);

        showVerifyResult(
            resultDiv,
            translator,
            reg
        );

    });


    input.addEventListener('keydown', e => {

        if (e.key === 'Enter') {

            btn.click();

        }

    });

}


/* ==================================================
   DISPLAY VERIFICATION RESULT
   ================================================== */

function showVerifyResult(
    container,
    translator,
    query
) {

    container.classList.add('show');

    if (translator) {

        container.className =
            'verify-result show success';

        const languages = (translator.languages || [])
            .map(escapeHTML)
            .join(' | ');

        container.innerHTML = `

            <div class="verify-result-icon">✅</div>

            <h4>Verified — Registration Found</h4>

            <p>
                <strong>Name:</strong>
                ${escapeHTML(translator.name)}
            </p>

            <p>
                <strong>Registration:</strong>
                ${escapeHTML(translator.regNumber)}
            </p>

            <p>
                <strong>Address:</strong>
                ${escapeHTML(translator.address)}
            </p>

            <p>
                <strong>Telephone:</strong>
                ${escapeHTML(translator.tel)}
            </p>

            <p>
                <strong>District:</strong>
                ${escapeHTML(translator.district)}
            </p>

            <p>
                <strong>Languages:</strong>
                ${languages}
            </p>

        `;

    } else {

        container.className =
            'verify-result show error';

        container.innerHTML = `

            <div class="verify-result-icon">❌</div>

            <h4>Not Found</h4>

            <p>
                No translator found with registration number
                "${escapeHTML(query)}".
            </p>

            <p>
                Please check the number and try again,
                or contact the administration.
            </p>

        `;

    }

}

